import json, re, collections, difflib, csv
W={e['uid']:e for e in json.load(open('/app/watchlist.json'))}
S2L=json.load(open('script2lat.json'))
PART={'al','el','bin','ibn','ben','b','bint','de','la','van','der','den','of','and','the','abd','le','du','mac'}
def toks(n):
    n=n.replace(',',' ')
    return [t for t in re.split(r'[\s\-.]+', n) if t]
def clean(n, sc=False):
    if sc:
        return [S2L.get(t,'?'+t) for t in n.split() if t not in ('بن',)]
    return [t.lower() for t in toks(n) if t.lower() not in PART and len(t)>1]
cust={r['customer_id']:r for r in csv.DictReader(open('/app/dev/customers_dev.csv'))}
ops=collections.Counter(); ex=collections.defaultdict(set)
pairs=set()
for r in csv.DictReader(open('/app/dev/labels_dev.csv')):
    if r['expected_decision']!='MATCH': continue
    e=W[r['expected_uid']]; c=cust[r['customer_id']]
    if e['type']!='individual': continue
    cn=c['full_name']
    if not re.search(r'[A-Za-z]',cn): continue
    ct=clean(cn)
    best=None
    for nm in [e['primary_name']]+[a['name'] for a in e['aliases'] if a['strength']=='strong']:
        et=clean(nm, not re.search(r'[A-Za-z]',nm))
        if len(et)==len(ct): best=et if best is None else best
    if best is None: continue
    # align by best assignment (sorted by similarity)
    used=set()
