SEED = int(sys.argv[1]) if len(sys.argv) > 1 else 11
random.seed(SEED)

PARTICLE = E.NASAB | E.ARTICLES | {"de", "la", "le", "du", "van", "der"}


def lang_of(e):
    s = (e.get("script_name") or "") + (e.get("primary_name") or "")
    if E.is_cyrillic(s):
        return "ru"
    if E.is_arabic(s):
        return "ar"
    return "lat"


def canon_tokens(e):
    """(given..., family) canonical latin tokens of an entry, plus nasab."""
    lat = G.canonical_latin(e)
    if not lat:
        return None
    toks = [t for t in re.split(r"[\s,]+", lat) if t]
    core, nasab, patro = [], [], []
    i = 0
    while i < len(toks):
        t = toks[i]
        low = re.sub(r"[^a-z]", "", E.fold(t))
        if low in E.NASAB and i + 1 < len(toks):
            nasab.append(toks[i + 1])
            i += 2
            continue
        if low in E.ARTICLES:
            i += 1
            continue
        m = re.match(r"^(al|el)-(.+)$", t.lower())
        if m:
            t = m.group(2)
        if E.PATRO_RE.search(low):
            patro.append(t)
            i += 1
            continue
        if len(low) > 1:
            core.append(t)
        i += 1
    if len(core) < 2:
        return None
    return core, nasab, patro


# canonical index for decoy validation -------------------------------------
index = collections.defaultdict(list)
entries = {}
pools = collections.defaultdict(set)
for e in W:
    if e["type"] != "individual":
