    if not cands:
        return None
    cands.sort()
    return cands[0][1]


rows, labels = [], []
n = 0


def emit(name, dob, e, dec, uid, cls):
    global n
    n += 1
    cid = "F%06d" % n
    rows.append({"customer_id": cid, "full_name": name, "dob": dob,
