                   "expected_uid": uid or "", "class": cls})


CONVS = ["turkish", "indonesian", "gulf", "plain", "noise",
         "sci", "scix", "polish", "german", "french"]

for uid, (e, core, nasab, patro) in entries.items():
    L = lang_of(e)
    convs = (["turkish", "indonesian", "gulf", "plain", "noise"] if L == "ar"
             else ["sci", "scix", "polish", "german", "french", "noise"])
    # ---- true match
    if random.random() < 0.55:
        conv = random.choice(convs)
        nm = render(e, core, nasab, patro, conv)
        if nm:
            dob = dob_variant(e["dob"])
            key = tuple(sorted(x.lower() for x in core))
            exp = expected_uid(key, dob)
            if exp:
                emit(nm, dob, e, "MATCH", exp, "T_" + L + "_" + conv)
    # ---- near-name decoy: swap one core token for a different pool name
    if random.random() < 0.5:
        conv = random.choice(convs)
        pos = 0 if (len(core) < 2 or random.random() < 0.5) else len(core) - 1
        role = "given" if pos == 0 else "family"
        alt = random.choice(sorted(pools[(L, role)]))
        newcore = list(core)
        newcore[pos] = alt
        if alt.lower() != core[pos].lower():
