def _expand(forms, pattern, repls, cap=16):
    """Replace every occurrence of pattern by each replacement (all combos)."""
    rx = re.compile(pattern)
    out = set()
    for f in forms:
        parts = rx.split(f)
        hits = rx.findall(f)
        if not hits:
            out.add(f)
            continue
        cur = [parts[0]]
        for idx, _h in enumerate(hits):
            nxt = []
            for c in cur:
                for r in repls:
                    nxt.append(c + r + parts[idx + 1])
            cur = nxt
            if len(cur) > cap:
                cur = cur[:cap]
        out |= set(cur)
        if len(out) > 64:
            break
    return out


